public class OwnedMultiTimingState {
 public static String mode='pass';
 public static List<Map<String,Object>> events=new List<Map<String,Object>>();
 public static void reset(String nextMode){mode=nextMode;events=new List<Map<String,Object>>();}
 private static void record(String phase,Account row){
  events.add(new Map<String,Object>{'phase'=>phase,'multi'=>row.OwnedMultiTimingSelection__c,'text'=>row.Description});
 }
 public static void beforeRows(List<Account> rows){
  for(Account row:rows){
   record('beforeInput',row);
   if(mode=='produce')row.OwnedMultiTimingSelection__c=Trigger.isInsert?';':';;';
   if(mode=='produceValid')row.OwnedMultiTimingSelection__c='Beta';
   record('beforeReturn',row);
  }
 }
 public static void afterRows(List<Account> rows){for(Account row:rows)record('after',row);}
}

@IsTest private class OwnedMultiTimingProbe {
 private static Map<String,Object> observe(String shape){
  Boolean updating=shape.endsWith('Update');
  Account row=new Account(Name='Owned multi timing',OwnedMultiTimingSelection__c='Alpha');
  if(updating){OwnedMultiTimingState.reset('pass');insert row;row.Name='Owned multi timing updated';}
  String mode=shape.startsWith('produced')?'produce':'pass';
  if(shape=='producedValidInsert')mode='produceValid';
  OwnedMultiTimingState.reset(mode);
  if(shape=='suppliedInsert')row.OwnedMultiTimingSelection__c=';';
  if(shape=='suppliedUpdate')row.OwnedMultiTimingSelection__c=';;';
  if(shape=='unknownInsert')row.OwnedMultiTimingSelection__c='NotDefined';
  if(shape=='textFenceInsert')row.Description=';';
  Map<String,Object> out=new Map<String,Object>{'shape'=>shape,'suppliedMulti'=>row.OwnedMultiTimingSelection__c,
   'restricted'=>Account.OwnedMultiTimingSelection__c.getDescribe().isRestrictedPicklist()};
  Boolean succeeded=false;
  try {
   if(updating)update row;else insert row;
   succeeded=true;
  }catch(DmlException e){out.put('errorType',e.getTypeName());out.put('status',String.valueOf(e.getDmlType(0)));}
  out.put('succeeded',succeeded);
  out.put('callerMulti',row.OwnedMultiTimingSelection__c);
  out.put('callerText',row.Description);
  out.put('events',OwnedMultiTimingState.events);
  if(succeeded){
   Account stored=[SELECT OwnedMultiTimingSelection__c,Description FROM Account WHERE Id=:row.Id];
   out.put('storedMulti',stored.OwnedMultiTimingSelection__c);out.put('storedText',stored.Description);
  }
  return out;
 }
 @IsTest static void suppliedInsert(){System.assert(false,'OWNED_MULTI_TIMING='+JSON.serialize(observe('suppliedInsert')));}
 @IsTest static void suppliedUpdate(){System.assert(false,'OWNED_MULTI_TIMING='+JSON.serialize(observe('suppliedUpdate')));}
 @IsTest static void producedInsert(){System.assert(false,'OWNED_MULTI_TIMING='+JSON.serialize(observe('producedInsert')));}
 @IsTest static void producedUpdate(){System.assert(false,'OWNED_MULTI_TIMING='+JSON.serialize(observe('producedUpdate')));}
 @IsTest static void producedValidInsert(){System.assert(false,'OWNED_MULTI_TIMING='+JSON.serialize(observe('producedValidInsert')));}
 @IsTest static void textFenceInsert(){System.assert(false,'OWNED_MULTI_TIMING='+JSON.serialize(observe('textFenceInsert')));}
 @IsTest static void unknownInsert(){System.assert(false,'OWNED_MULTI_TIMING='+JSON.serialize(observe('unknownInsert')));}
}

