trigger OwnedMultiTimingTrigger on Account (before insert,before update,after insert,after update) {
 if(Trigger.isBefore)OwnedMultiTimingState.beforeRows(Trigger.new);
 else OwnedMultiTimingState.afterRows(Trigger.new);
}
